await browserjs(tabId, () => {
  const radio = Array.from(document.querySelectorAll('input[type="radio"], [role="radio"], span, label'))
    .find(el => el.innerText && el.innerText.trim().includes('1 stop or fewer'));
  if (radio) radio.click();
});
await new Promise(r => setTimeout(r, 1000));

// Close stops dialog
await browserjs(tabId, () => {
  const closeBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === 'Close' || b.getAttribute('aria-label') === 'Close dialog' || b.innerText.trim() === 'OK');
  if (closeBtn) closeBtn.click();
});
await new Promise(r => setTimeout(r, 1000));

// Now click "Times"
await browserjs(tabId, () => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim().startsWith('Times'));
  if (btn) btn.click();
});
await new Promise(r => setTimeout(r, 1000));

const timesContent = await browserjs(tabId, () => {
  const dialog = document.querySelector('[role="dialog"], [role="menu"], div[class*="dialog"]');
  return dialog ? dialog.innerText : document.body.innerText.slice(0, 1500);
});
console.log("Times dialog:", timesContent);
"}
